# font_bitmap TEXT — prints 5 rows of '#' and ' '.
font_bitmap() {
    local text="${1^^}" rows=("" "" "" "" "") i r ch
    local -a g
    for (( i = 0; i < ${#text}; i++ )); do
        ch="${text:i:1}"
        IFS='|' read -ra g <<<"${FONT_GLYPHS[$ch]:-${FONT_GLYPHS[" "]}}"
        for r in 0 1 2 3 4; do
            (( i > 0 )) && rows[r]+=" "
            rows[r]+="${g[r]}"
        done
    done
    printf '%s\n' "${rows[@]}"
}

# font_render TEXT STYLE — prints the banner lines; "default" prints nothing.
font_render() {
    local -a rows; mapfile -t rows < <(font_bitmap "$1")
    local w=${#rows[0]} y x line t u
    case "$2" in
        block) for line in "${rows[@]}"; do printf '%s\n' "${line//#/█}"; done ;;
        shade) for line in "${rows[@]}"; do printf '%s\n' "${line//#/▓}"; done ;;
        half)
            rows+=("$(printf '%*s' "$w" '')")
            for (( y = 0; y < 6; y += 2 )); do
                line=""
                for (( x = 0; x < w; x++ )); do
                    t="${rows[y]:x:1}"; u="${rows[y+1]:x:1}"
                    if [[ $t == "#" && $u == "#" ]]; then line+="█"; elif [[ $t == "#" ]]; then line+="▀"
                    elif [[ $u == "#" ]]; then line+="▄"; else line+=" "; fi
                done
                printf '%s\n' "$line"
            done ;;
        slant) for (( y = 0; y < 5; y++ )); do line="${rows[y]//#/█}"; printf '%*s%s\n' $(( 4 - y )) '' "$line"; done ;;
    esac
    return 0
}
